{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 금연환경 조성 및 간접흡연 피해방지조례상 간접흡연에 담배 연기 사라진 뒤 옷·가구에 밴 물질 노출이 포함되는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 금연환경 조성 및 간접흡연 피해방지조례 제2조제3호는 간접흡연을 비흡연자가 흡연 시 발생하는 유해 물질에 노출되는 것으로 정의하면서, 담배 연기에 직접 노출되는 2차 흡연과 흡연자의 옷, 벽, 가구 등에 흡착된 유해 물질이 다시 공기 중으로 배출되는 과정을 거쳐 비흡연자에게 보다 장기간 피해를 미칠 수 있는 3차 흡연을 모두 포함한다고 정하고 있다. 따라서 담배 연기가 사라진 뒤 옷이나 가구에 밴 물질에 노출되는 것도 조례상 간접흡연에 포함된다.",
          "b_ids": "금연:제2조제3호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
